from pathlib import Path
import json,re,time,hashlib
from playwright.sync_api import sync_playwright,expect
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'evidence/浏览器验收';OUT.mkdir(parents=True,exist_ok=True)
def main():
    checks=[];errors=[]
    def check(name,ok):
        checks.append(dict(name=name,passed=bool(ok)))
        assert ok,name
    with sync_playwright() as w:
        b=w.chromium.launch(headless=True,channel='msedge')
        ctx=b.new_context(viewport={'width':1440,'height':1000},offline=True,accept_downloads=True)
        p=ctx.new_page();p.on('pageerror',lambda e:errors.append(str(e)))
        p.goto((ROOT/'广东数学竞赛成绩查询.html').as_uri());expect(p.locator('#summary')).to_contain_text('条记录')
        db=json.loads((ROOT/'data/查询数据.json').read_text(encoding='utf-8'))
        def count():return int(re.search(r'([\d,]+) 条记录',p.locator('#summary').inner_text()).group(1).replace(',',''))
        def person_count():return int(re.search(r'([\d,]+) 份选手档案',p.locator('#summary').inner_text()).group(1).replace(',',''))
        def search(q):p.locator('#query').fill(q);p.locator('#searchForm button').click()
        check('离线加载全部真实记录',count()==len(db['records']))
        check('默认按个人档案去重展示',person_count()==len(db['people']) and p.locator('#peopleView').get_attribute('aria-pressed')=='true')
        p.screenshot(path=str(OUT/'桌面-首页.png'))
        check('首页隐藏高级筛选与长说明',p.locator('#advancedFilters').is_hidden() and not p.locator('.data-notes').get_attribute('open'))
        p.locator('#advanced').check();check('高级搜索实际展开筛选',p.locator('#advancedFilters').is_visible())
        p.locator('#next').click();check('翻页后显示41起',p.locator('#range').inner_text().startswith('显示 41'))
        p.locator('#prev').click()
        search('薛浩琛');check('薛浩琛历年高联与初赛合为一行',person_count()==1 and count()==3 and p.locator('.people tbody tr').count()==1)
        p.screenshot(path=str(OUT/'桌面-个人合并查询.png'))
        p.locator('.name').click();check('个人详情包含2025与2026',all(y in p.locator('#detailBody').inner_text() for y in ['2025','2026']))
        p.screenshot(path=str(OUT/'桌面-薛浩琛个人页.png'))
        profile_url=p.url;p.locator('#closeDetail').click()
        linked=ctx.new_page();linked.goto(profile_url);expect(linked.locator('#detail')).to_be_visible();linked.reload();expect(linked.locator('#detail')).to_be_visible();check('个人链接新页及刷新直达同一档案','薛浩琛' in linked.locator('#detailTitle').inner_text());linked.close()
        search('李泽熙');check('李泽熙两校同名分成两份档案',person_count()==2 and count()==10)
        p.locator('.people tbody tr').filter(has_text='深圳中学').locator('.name').click()
        check('详情没有混入另一同名者学校',p.locator('.profiletable').inner_text().count('华南师范大学附属中学')==0 and p.locator('.profiletable tbody tr').count()==5)
        check('其他同名档案有核对入口',p.locator('.related-person').count()==1)
        p.locator('.related summary').click();p.locator('.related-person').click();check('可切换另一同名者且记录独立',p.locator('.profiletable tbody tr').count()==5 and '华南师范大学附属中学' in p.locator('#identityNote').inner_text());p.locator('#closeDetail').click()
        search('王梓墨');check('校名变化三年归为一个人',person_count()==1 and count()==5)
        p.locator('#reset').click();search('冯晨旭');p.locator('#competition').select_option('IMO');check('按IMO筛出单人且保留完整履历',person_count()==1 and count()==1)
        p.locator('.name').click();check('筛选后个人页仍汇总高联CMOIMO五条',p.locator('.profiletable tbody tr').count()==5 and all(k in p.locator('.profiletable').inner_text() for k in ['高联','CMO','IMO']))
        check('详情按PersonInfo只显示选手信息与获奖表',p.locator('#detailTitle').inner_text()=='冯晨旭' and [x.inner_text() for x in p.locator('#detailBody h3').all()]==['选手信息','比赛记录'] and p.locator('.profile-notes').get_attribute('open') is None)
        p.locator('#closeDetail').click();p.locator('#reset').click();p.locator('#recordsView').click()
        search('李泽熙');n=count();check('中文姓名可查询',n>=3)
        chinese=p.locator('.records tbody').inner_text()
        for q in ['lizexi','LI ZE XI','lzx']:
            search(q);check('拼音检索 '+q,'李泽熙' in p.locator('#result').inner_text())
            if q!='lzx':check('全拼与中文结果一致 '+q,count()==n)
        search('冯晨旭');p.locator('#competition').select_option('IMO');check('IMO冯晨旭官方世界17名31分',count()==1 and '17' in p.locator('#result').inner_text() and '31' in p.locator('#result').inner_text())
        p.locator('.name').click();expect(p.locator('#detail')).to_be_visible();check('跨赛事同名历年记录',p.locator('#detailBody').inner_text().count('CMO')>=1)
        p.screenshot(path=str(OUT/'桌面-选手详情.png'));p.locator('#closeDetail').click()
        p.locator('#reset').click();p.locator('#year').select_option('2026');p.locator('#award').select_option('省队');check('2026省队38条',count()==38)
        p.locator('#reset').click();p.locator('#competition').select_option('CMO');p.locator('#year').select_option('2024');check('2024CMO广东38条',count()==38)
        p.locator('#reset').click();search('黄梓睿');p.locator('#year').select_option('2026');p.locator('#competition').select_option('高联');p.locator('#award').select_option('二等奖');check('同校同名原始标记不合并',count()==2 and '[1]' in p.locator('#result').inner_text() and '[2]' in p.locator('#result').inner_text())
        with p.expect_download() as dl:p.locator('#export').click()
        fn=OUT/'筛选导出.csv';dl.value.save_as(fn);data=fn.read_text(encoding='utf-8-sig');check('导出当前筛选含名次顺位和同名标记',len(data.strip().splitlines())==3 and '官方名次' in data)
        p.locator('#reset').click();p.locator('#award').select_option('报名未见获奖');check('报名比对未区分缺考',count()>0 and '未区分' in p.locator('#result').inner_text())
        for year in ['2020','2025','2026']:
            p.locator('#year').select_option(year);check(year+'报名差集实际可筛选',count()==sum(r['year']==int(year) and r['award']=='报名未见获奖' for r in db['records']))
        p.locator('#reset').click();p.locator('#award').select_option('报名匹配待核');check('有疑问的报名匹配另列待核',count()>0 and '省报名' not in p.locator('#result').inner_text())
        search('abcdefxyznotexists');check('无结果且不推断未获奖',count()==0 and '不代表' in p.locator('#result').inner_text())
        p.locator('#reset').click();search('李泽熙');p.locator('#year').select_option('2026');p.locator('.src button').first.click()
        anchor=p.locator('#detailBody .profile-notes a').first;href=anchor.get_attribute('href')
        with p.expect_popup() as pop:anchor.click()
        popup=pop.value;popup.wait_for_timeout(1000);print('PDF POPUP',popup.url,'LINK',href,flush=True);check('实际点击打开对应本地PDF页',popup.url.startswith('file:') and '.pdf' in popup.url and '#page=' in popup.url);popup.close();p.locator('#closeDetail').click()
        p.locator('#reset').click();p.locator('#peopleView').click()
        first=p.locator('.people .name').first.inner_text()
        check('默认首页最高荣誉为IMO且不是按年份',first.startswith(db['people'][0]['name']) and 'IMO' in p.locator('.people tbody tr').first.inner_text())
        search('官浩楠');check('官浩楠初赛与高联报名归同一人',person_count()==1 and count()==3)
        p.locator('.name').click();t=p.locator('.profiletable').inner_text()
        check('官浩楠2025报名原表高三且不认定缺考',all(v in t for v in ['2024','2025','高三','原表年级','未获奖 / 缺考（未区分）']))
        p.screenshot(path=str(OUT/'桌面-官浩楠个人页.png'));p.locator('#closeDetail').click()
        search('杨奕辰');p.locator('.name').click();t=p.locator('.profiletable').inner_text()
        check('杨奕辰高一考场及2024初赛已补齐',p.locator('.profiletable tbody tr').count()==6 and all(v in t for v in ['2024','高一','广东初赛','一等奖']))
        p.screenshot(path=str(OUT/'桌面-杨奕辰个人页.png'))
        p.locator('.profile-school button').first.click();check('个人页学校链接进入学校选手列表',p.locator('#detail').is_hidden() and p.locator('#school').input_value()=='深圳中学')
        p.locator('[data-tab="schools"]').click();p.locator('#schoolQuery').fill('深圳中学')
        check('独立学校表可搜索',p.locator('#schoolList tbody tr').count()>=1 and p.locator('#schoolList button').filter(has_text='深圳中学').count()>=1)
        p.screenshot(path=str(OUT/'桌面-学校目录.png'))
        school_url=p.url;linked=ctx.new_page();linked.goto(school_url);expect(linked.locator('#schools')).to_be_visible();linked.close();check('学校目录链接刷新仍保留页面',True)
        p.locator('#schoolList [data-school="深圳中学"]').click();check('学校目录实际点击筛出选手',p.locator('#records').is_visible() and p.locator('#school').input_value()=='深圳中学')
        p.locator('[data-tab="contests"]').click();p.locator('#contestQuery').fill('2024高联')
        check('独立比赛表可按年份比赛搜索',p.locator('#contestList tbody tr').count()==1)
        p.screenshot(path=str(OUT/'桌面-比赛目录.png'))
        p.locator('#contestList [data-contest]').click();check('比赛目录点击进入当场成绩',p.locator('#competition').input_value()=='高联' and p.locator('#year').input_value()=='2024' and p.locator('#recordsView').get_attribute('aria-pressed')=='true')
        p.locator('.name').first.click();p.locator('.contest-name').first.click();check('个人页比赛链接实际打开对应赛事',p.locator('#detail').is_hidden() and p.locator('#recordsView').get_attribute('aria-pressed')=='true')
        p.locator('[data-tab="scoring"]').click();check('评分页公开公式与自定义边界',all(v in p.locator('#scoring').inner_text() for v in ['0.4','IMO','自定义','学校评分']))
        p.screenshot(path=str(OUT/'桌面-评分规则.png'))
        p.locator('[data-tab="coverage"]').click();check('年度矩阵包含高联CMO与IMO',all(x in p.locator('#coverage').inner_text() for x in ['2020','2026','CMO','IMO','广东初赛','专项核对1名']))
        p.screenshot(path=str(OUT/'桌面-年度收录.png'))
        p.locator('[data-tab="sources"]').click();check('全部来源可见',p.locator('.sourceitem').count()==len(db['sources']))
        p.locator('[data-tab="records"]').click();p.locator('#reset').click();p.locator('#peopleView').click()
        p.locator('#advanced').uncheck();p.set_viewport_size({'width':390,'height':844});p.screenshot(path=str(OUT/'窄屏-首页.png'))
        check('390窄屏无页面横向溢出',p.evaluate('document.documentElement.scrollWidth<=innerWidth'))
        search('薛浩琛');p.locator('#result').scroll_into_view_if_needed();p.screenshot(path=str(OUT/'窄屏-个人合并查询.png'));check('窄屏同一人只显示一张卡片',p.locator('.people tbody tr').count()==1)
        search('冯晨旭');p.locator('.name').first.click();p.screenshot(path=str(OUT/'窄屏-选手详情.png'));check('窄屏详情可打开关闭',p.locator('#detail').is_visible());p.keyboard.press('Escape')
        p.locator('[data-tab="schools"]').click();p.screenshot(path=str(OUT/'窄屏-学校目录.png'));check('窄屏学校目录无页面溢出',p.evaluate('document.documentElement.scrollWidth<=innerWidth'))
        check('无JavaScript运行错误',not errors)
        report=dict(status='passed',browser='Microsoft Edge headless',offline=True,checks=checks,check_count=len(checks),errors=errors,
                    html_sha256=hashlib.sha256((ROOT/'广东数学竞赛成绩查询.html').read_bytes()).hexdigest(),screenshots=[f.name for f in OUT.glob('*.png')])
        (OUT/'浏览器检查.json').write_text(json.dumps(report,ensure_ascii=False,indent=2),encoding='utf-8')
        print('PASS',len(checks),'checks');b.close()
if __name__=='__main__':main()
